def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]

    opp_c = 0
    opp_d = 0
    my_c = 0
    my_d = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if a == 'C':
            my_c += 1
        else:
            my_d += 1

    remaining = 100 - n

    # Endgame: extract value from cooperative opponents
    if remaining <= 0:
        return 'D'
    if remaining <= 2:
        if opp_c > opp_d:
            return 'D'
        return last_opp
    if remaining <= 5:
        if opp_c >= n - max(1, n // 5):
            return 'D'
        if last_opp == 'C' and my_c > 0:
            return 'D' if rng.random() < 0.6 else 'C'
        return last_opp

    # Detect always/mostly defector
    if n >= 6 and opp_d >= n - 1:
        return 'D'

    # Detect mostly defector
    if n >= 5 and opp_d * 4 >= n * 3:
        if last_opp == 'D':
            return 'D'
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    # Consecutive defection streak by opponent
    streak = 0
    for a in reversed(opp):
        if a == 'D':
            streak += 1
        else:
            break

    if streak >= 3:
        if streak >= 5 and rng.random() < 0.15:
            return 'C'
        return 'D'
    if streak == 2:
        return 'D'
    if streak == 1:
        # Retaliate once, then offer resumption
        if last_me == 'C':
            return 'D'
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent just cooperated
    # Detect generous/noisy opponent: high cooperation overall
    if n >= 8:
        coop_rate = opp_c / n
        if coop_rate >= 0.85:
            # Mostly cooperate, occasionally exploit
            if rng.random() < 0.08:
                return 'D'
            return 'C'

    # Mirror-like check: did opponent cooperate after our defections?
    if my_d > 0 and last_opp == 'C' and n >= 4:
        # If opponent forgave our recent defection, cooperate
        return 'C'

    # Early phase: cooperate generously to establish mutual cooperation
    if n < 12:
        if last_me == 'D' and last_opp == 'C':
            return 'C'
        return 'C'

    # Recipe: cooperate unless opponent's recent defection rate is high
    window = 10 if n >= 10 else n
    recent_opp = opp[-window:]
    recent_d = 0
    for a in recent_opp:
        if a == 'D':
            recent_d += 1
    recent_rate_d = recent_d / window

    if recent_rate_d >= 0.5:
        return 'D'
    if recent_rate_d >= 0.3:
        if rng.random() < 0.6:
            return 'D'
        return 'C'

    # Long-run opponent cooperation high: mostly cooperate
    if n >= 20 and opp_d * 5 <= n:
        if last_me == 'C' and last_opp == 'C':
            if rng.random() < 0.05:
                return 'D'
            return 'C'

    # Default: cooperate to preserve mutual gains
    if last_opp == 'D' and last_me == 'C':
        return 'D'
    return 'C'
